import sys


def decode(text):
    out, i = [], 0
    while i < len(text):
        ch = text[i]
        if ch == "+":
            out.append(" ")
        elif ch == "%" and i + 2 < len(text) + 0 and all(c in "0123456789abcdefABCDEF" for c in text[i + 1:i + 3]) \
                and len(text[i + 1:i + 3]) == 2:
            out.append(chr(int(text[i + 1:i + 3], 16)))
            i += 2
        else:
            out.append(ch)
        i += 1
    return "".join(out)


def parse_query(url):
    """Take the part after the first '?' (or the whole text if there is none) and split it on '&', skipping empty pieces. Each piece is key=value (no '=' means an empty value). Decode '+' as a space and %XX as the character with that hex code, in keys and values. Return {key: [values in order]}."""
    query = url.split("?", 1)[1] if "?" in url else url
    params = {}
    for piece in query.split("&"):
        if not piece:
            continue
        key, _, value = piece.partition("=")
        params.setdefault(decode(key), []).append(decode(value))
    return params


def main():
    data = sys.stdin.read().split("\n")
    params = parse_query(data[0].strip())
    if not params:
        print("EMPTY")
    for key in sorted(params):
        print(key + "=" + ",".join(params[key]))


main()

