import sys


def bundle_size(modules, entry):
    """modules: {name: (size in KB, [modules it imports])}; imports can form cycles. Return the total KB of every module reachable from entry, counting each module once, including entry itself."""
    seen, stack = {entry}, [entry]
    while stack:                                   # depth-first search; `seen` stops cycles
        for dep in modules[stack.pop()][1]:
            if dep not in seen:
                seen.add(dep)
                stack.append(dep)
    return sum(modules[m][0] for m in seen)


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    modules = {}
    for i in range(n):
        name, kb, deps = data[1 + i].split()
        modules[name] = (int(kb), [] if deps == "-" else deps.split(","))
    for entry in data[1 + n].split():
        print(entry, bundle_size(modules, entry))


main()

import sys


def run_sale(events, hold):
    """events: (second, HOLD|RELEASE|BUY, seat, user) in time order. A hold lasts `hold` seconds (it has expired at second >= start + hold). HOLD works if the seat is not sold and nobody else holds it (holding your own seat again restarts the timer). RELEASE works only for the current holder. BUY works only for the current holder of an unexpired hold, and sells the seat. Anything else is rejected. Return ([(seat, buyer)] sorted by seat, number of rejected events)."""
    holder, expires, sold = {}, {}, {}
    rejected = 0
    for t, action, seat, user in events:
        held_by = holder.get(seat) if seat in holder and t < expires[seat] else None   # expired holds vanish
        if seat in sold:
            rejected += 1
        elif action == "HOLD" and held_by in (None, user):
            holder[seat], expires[seat] = user, t + hold
        elif action == "RELEASE" and held_by == user:
            del holder[seat], expires[seat]
        elif action == "BUY" and held_by == user:
            sold[seat] = user
        else:
            rejected += 1
    return sorted(sold.items()), rejected


def main():
    data = sys.stdin.read().split("\n")
    hold = int(data[0])
    n = int(data[1])
    events = []
    for i in range(n):
        t, action, seat, user = data[2 + i].split()
        events.append((int(t), action, seat, user))
    sold, rejected = run_sale(events, hold)
    for seat, user in sold:
        print(seat, user)
    print("rejected", rejected)


main()
